#include <iostream>
#include <vector>
#include <algorithm>
#include <map>

int main() {
    std::vector<int> values(2);
    for (int i = 0; i < 2; ++i) {
        std::cin >> values[i];
    }
    std::sort(values.begin(), values.end());
    int a = values[0];
    int b = values[1];
    int product = a * b;
    int correction = 0;
    if (a == 1) {
        correction = std::min(b % 6, 6 - b % 6);
    } else if (a == 2) {
        std::map<int, int> correction_map = {{2, 4}, {3, 2}, {7, 2}};
        auto it = correction_map.find(b);
        correction = (it != correction_map.end()) ? it->second : 0;
    } else {
        correction = (a & 1) * (b & 1);
    }
    std::cout << product - correction << std::endl;
    return 0;
}
